      {"id":"kap_chance_9","type":"chance","actionType":"back","amount":3,"amount2":0,"targetFieldId":"","textTemplate":{"ru":"Гравитационный манёвр не удался — вернитесь на {{amount}} сектора назад.","en":"The gravitational maneuver failed — move back {{amount}} sectors.","uk":"Гравітаційний маневр не вдався — поверніться на {{amount}} сектори назад."}},
      {"id":"kap_chance_10","type":"chance","actionType":"get","amount":50,"amount2":0,"targetFieldId":"","textTemplate":{"ru":"Вы продали добытые минералы. Получите {{amount}}.","en":"You sold the mined minerals. Receive {{amount}}.","uk":"Ви продали видобуті мінерали. Отримайте {{amount}}."}},
      {"id":"kap_chance_11","type":"chance","actionType":"goto","amount":0,"amount2":0,"targetFieldId":"oberon","textTemplate":{"ru":"На Обероне обнаружены редкие минералы — отправляйтесь туда для добычи.","en":"Rare minerals have been discovered on Oberon — go there to mine them.","uk":"На Обероні виявлено рідкісні мінерали — вирушайте туди для видобутку."}},
      {"id":"kap_chance_12","type":"chance","actionType":"goto","amount":0,"amount2":0,"targetFieldId":"titan","textTemplate":{"ru":"На Титане зарегистрирован выгодный контракт на доставку. Вы направляетесь туда для его выполнения.","en":"A lucrative delivery contract has been registered on Titan. You are heading there to fulfill it.","uk":"На Титані зареєстровано вигідний контракт на доставку. Ви прямуєте туди для його виконання."}},
      {"id":"kap_chance_13","type":"chance","actionType":"get","amount":10,"amount2":0,"targetFieldId":"","textTemplate":{"ru":"Ваш рождественский фонд созрел. Получите {{amount}}.","en":"Your Christmas fund has matured. Receive {{amount}}.","uk":"Ваш різдвяний фонд дозрів. Отримайте {{amount}}."}},
      {"id":"kap_chance_14","type":"chance","actionType":"pay","amount":15,"amount2":0,"targetFieldId":"","textTemplate":{"ru":"Заплатите налог на бедность — {{amount}}.","en":"Pay the poverty tax — {{amount}}.","uk":"Сплатіть податок на бідність — {{amount}}."}},
      {"id":"kap_chance_15","type":"chance","actionType":"pay","amount":150,"amount2":0,"targetFieldId":"","textTemplate":{"ru":"Заплатите школьный налог — {{amount}}.","en":"Pay the school tax — {{amount}}.","uk":"Сплатіть шкільний податок — {{amount}}."}},
      {"id":"kap_chance_16","type":"chance","actionType":"repair","amount":40,"amount2":115,"targetFieldId":"","textTemplate":{"ru":"Инфраструктурные сборы. Оплатите {{amount}} за модуль, {{amount2}} за купол.","en":"Infrastructure fees. Pay {{amount}} per module, {{amount2}} per dome.","uk":"Інфраструктурні збори. Сплатіть {{amount}} за модуль, {{amount2}} за купол."}}
